 private int dp(int n){return Aero.dp(getContext(),n);}void navigate(String id){TenSettingsCatalog.Page p=TenSettingsCatalog.page(id);page=id.equals("home")?"home":p!=null?id:TenSettingsCatalog.first(id);drawer=false;if(search.length()>0)search.setText("");else render();scroll.scrollTo(0,0);}
